class Pila {
    private int[] datos = new int[10];
    private int n = 0;
    void push(int x) { datos[n++] = x; }
    int pop() {
        if (n == 0) throw new IllegalStateException("pila vacia");
        return datos[--n];
    }
}
public class Main {
    public static void main(String[] args) {
        Pila p = new Pila();
        p.push(7);
        System.out.println(p.pop());
        try {
            System.out.println(p.pop());
        } catch (IllegalStateException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

