abstract class CharArrayOperation {
    abstract void doOperation(char[] a);
}
class Upper extends CharArrayOperation {
    void doOperation(char[] a) {
        for (int i = 0; i < a.length; i++) a[i] = Character.toUpperCase(a[i]);
    }
}
class Reverse extends CharArrayOperation {
    void doOperation(char[] a) {
        for (int i = 0; i < a.length / 2; i++) {
            char t = a[i];
            a[i] = a[a.length - 1 - i];
            a[a.length - 1 - i] = t;
        }
    }
}
public class Main {
    public static void main(String[] args) {
        char[] t = "hola mundo".toCharArray();
        CharArrayOperation[] ops = { new Upper(), new Reverse() };
        for (CharArrayOperation op : ops) op.doOperation(t);
        System.out.println(new String(t));
    }
}

